#nullable enable
using Marten;
using HourBooking.Contracts;

namespace HourBooking.Slices.Booking;

/// <summary>
/// The DECIDER for FillZeroHours: it receives the folded state and returns the event. Same job
/// BookHoursEndpoint does for book-hours, in a different transport.
///
/// It is a Wolverine MESSAGE handler rather than an HTTP endpoint because nobody types this command.
/// There is no screen in this slice — the ZeroFillProcessor issues it, in process, through
/// <c>IMessageBus.InvokeAsync&lt;ZeroFillOutcome&gt;</c>. Exposing an HTTP route for it would invent
/// public surface the model does not draw.
///
/// Two rules are deliberately NOT here, and their absence is the slice's most important behaviour:
///
///   * <b>HoursMustBeNonZero</b> — GWT 3, "the system may write a zero where an employee may not".
///     That rule is enforce="periphery" on book-hours and lives in BookHoursValidator, which validates
///     <c>BookHours</c>. FillZeroHours is a different command with no validator, so the automation's
///     path does not pass through it. This slice is the only way a zero enters the system.
///   * <b>NotAProjectMember</b> — the trigger for the whole slice is the employee LEAVING the project,
///     so every fill is by definition written against a project they are no longer a member of. A
///     membership check here would reject 100% of the work.
///
/// The state is fetched with FetchForWriting rather than [Aggregate]: that attribute resolves a stream
/// id from one route argument, and this stream is keyed by a composite (employeeId + month).
/// </summary>
public static class FillZeroHoursHandler
{
    public static async Task<ZeroFillOutcome> Handle(
        FillZeroHours command,
        IDocumentSession session,
        CancellationToken cancellation)
    {
        var stream = await session.Events.FetchForWriting<FillZeroHoursState>(
            FillZeroHoursState.StreamKey(command.EmployeeId, command.Month), cancellation);
        var sheet = stream.Aggregate ?? new FillZeroHoursState();

        // AlreadyFilled. The todo list already stops the processor working a row twice; this is the
        // rule enforced in the transaction, where a concurrent tick or a hand booking is visible.
        var standing = sheet.Standing(command.Date, command.ProjectId);
        if (standing is not null)
            return ZeroFillOutcome.Rejected("AlreadyFilled", standing.ZeroFilled
                ? $"{command.Date:yyyy-MM-dd} is already zero-filled for this project."
                : $"{command.Date:yyyy-MM-dd} already carries booked hours for this project, and only one line may stand per day+project.");

        stream.AppendOne(new ZeroHoursFilled(
            command.BookingId, command.EmployeeId, command.Month, command.ProjectId, command.Date,
            // terminal="hours:const" — the handler supplies the value, so the decider writes the
            // constant rather than whatever a caller put in the field.
            FillZeroHoursState.ZeroHours,
            DateTimeOffset.UtcNow));

        await session.SaveChangesAsync(cancellation);
        return ZeroFillOutcome.Filled(command.BookingId, command.Date);
    }
}

/// <summary>
/// What the decider answers the automation with.
///
/// This is a THIRD rejection shape, and it exists because an automation has no HTTP caller to hand a
/// ProblemDetails to. The other two:
///
///   periphery (FluentValidation middleware) -> { errors: { Hours: ["HoursMustBeWholeOrHalf"] } }
///   an HTTP decider (Rejections.Problem)    -> { title: "DailyCapExceeded", detail: "..." }
///
/// The part that is the same everywhere, and the part that matters, is that <see cref="Rule"/> carries
/// the model's rule name — a GWT says then="error: AlreadyFilled", so the name is the machine-readable
/// half and the prose is for a human.
/// </summary>
public sealed record ZeroFillOutcome(Guid? BookingId, DateOnly? Date, string? Rule, string? Detail)
{
    public bool WasFilled => Rule is null;

    public static ZeroFillOutcome Filled(Guid bookingId, DateOnly date) => new(bookingId, date, null, null);

    public static ZeroFillOutcome Rejected(string rule, string detail) => new(null, null, rule, detail);
}
